---lvl 7 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl8_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end			game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		sound.play("41-1")		if dialog.showMinTime("Level8-1", faceJingya,0) ==1 then break end		camera.setFollowRoleMode(false)		camera.gotoPosition(1040,912)		script.delay(0.6)		camera.gotoPosition(1015,1045)		script.delay(0.6)		camera.gotoPosition(926,765)		sound.play("54-1")		if dialog.show("Level8-2", faceDeyi) ==1 then break end		if dialog.showMinTime("Level8-3", faceZhoumei,0) ==1 then break end		camera.gotoRole()		sound.play("58-1")		if dialog.show("Level8-4", faceRenzhen) ==1 then break end		camera.setFollowRoleMode(true)				--set story viewed flag        global.setBool("lvl8_b1")		game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false		isSkip = false				until trueendonRoleReachedMoon = function()     game.pauseLogic()	sound.play("54-1")    dialog.show("Level8-5", faceDeyi)    game.success()endif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end